  ['বড় গাছে উপরিপ্রয়োগ','গোড়া থেকে কিছুটা দূরে ওপরের মাটি আলগা করে অল্প সার ছড়িয়ে মিশিয়ে দিন। কাণ্ডের সঙ্গে সার স্তূপ করবেন না। প্রয়োগের পরে মাটি ভিজিয়ে দিন যাতে সার সমানভাবে মেশে।'],
  ['সংরক্ষণ ও পর্যবেক্ষণ','প্যাকেট শুকনো ও ছায়াযুক্ত স্থানে রাখুন। মাটি ভিজে দুর্গন্ধ হলে আগে নিষ্কাশন ঠিক করুন। গাছের ফলাফল দেখতে সময় দিন; একসঙ্গে একাধিক সার অতিরিক্ত দেবেন না।']],
  'faq'=>['ভার্মিকম্পোস্ট কি সরাসরি পাতায় দিতে হয়?','এটি মাটিতে ব্যবহারের জন্য; পণ্যের লেবেলে আলাদা নির্দেশনা না থাকলে পাতায় দেবেন না।'],'products'=>['vermicompost']],
 ['slug'=>'taharat-tricho-compost-how-to-use','title'=>'Taharat Agro ট্রাইকো কম্পোস্ট ব্যবহারের নিয়ম ও সতর্কতা','intro'=>'Taharat Agro ট্রাইকো কম্পোস্টে ট্রাইকোডার্মা সমৃদ্ধ জৈব উপাদান আছে। এটি মাটির পরিচর্যায় ব্যবহার করা যায়, কিন্তু পানি জমা, অসুস্থ শিকড় বা ভুল পরিবেশের একমাত্র সমাধান নয়।','sections'=>[
  ['ব্যবহারের আগে','প্যাকেটের মেয়াদ, সংরক্ষণ ও পরিমাণ নির্দেশনা দেখুন। অতিরিক্ত রোদ বা ভেজা জায়গায় পণ্য খোলা রাখবেন না। পরিষ্কার, ঝুরঝুরে ও নিষ্কাশনযুক্ত মাটিতে ব্যবহার করুন।'],
  ['পটিং মিক্সে মেশানো','নির্দেশিত পরিমাণ মাটির সঙ্গে সমানভাবে মিশিয়ে চারা রোপণ করুন। পুরোনো টবে প্রয়োগ করলে ওপরের মাটি আলগা করে গোড়া থেকে দূরে দিন। সারের স্তূপে শিকড় ঢেকে ফেলবেন না।'],
  ['পরে কী দেখবেন','পানি জমছে কি না এবং গাছের নতুন বৃদ্ধি কেমন তা দেখুন। রোগের লক্ষণ থাকলে শুধু পণ্য প্রয়োগে নির্ভর না করে কারণ শনাক্ত করুন। রাসায়নিক ছত্রাকনাশকের সঙ্গে ব্যবহারের বিষয়ে লেবেল বা বিশেষজ্ঞের নির্দেশনা অনুসরণ করুন।']],
  'faq'=>['ট্রাইকো কম্পোস্ট দিলেই কি শিকড় পচা সেরে যাবে?','না। নিষ্কাশন, পানি ও আক্রান্ত মাটির সমস্যা আগে ঠিক করতে হবে।'],'products'=>['trichoderma-compost']],
